data.transform:
(
  $companyInfo:= $appConfig.companyInformation;

  {
    "input": $,
    "packBy": $appConfig.packOptions.method,
    "companyInformation": 
      $companyInfo ~> |$|{
        "textAddress": Address1 & ($exists(Address2) and Address2 != "" ? " " & Address2 : ""),
        "fullAddress": Address1 
          & ($exists(Address2) and Address2 != "" ? " " & Address2 : "")
          & " " & City 
          & ", " & StateProvince 
          & " " & PostalCode 
          & " " & Country
      }|
  }
)

data.query:
query Inventory($where: InventoryWhereInput, $orderBy: [InventoryOrderByInput!], $first: Int, $after: String) {
  inventory(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        serialNumber
        inventoryStatusId
      }
    }
  }
}

query Shipment($where: ShipmentWhereInput, $orderBy: [ShipmentOrderByInput!], $first: Int, $after: String) {
  shipment(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
      }
    }
  }
}

query Order($where: OrderWhereInput, $orderBy: [OrderOrderByInput!], $first: Int, $after: String) {
  order(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        number
        orderStatusId
      }
    }
  }
}

query Load($where: LoadWhereInput, $orderBy: [LoadOrderByInput!], $first: Int, $after: String) {
  load(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        number
      }
    }
  }
}

